def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def step_toward(a, b):
        return [clamp_step(b[0] - a[0]), clamp_step(b[1] - a[1])]

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def first_pair(v):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return [v[0], v[1]]
        return None

    def norm_points(v):
        if not v:
            return []
        pts = []
        for item in v:
            p = first_pair(item)
            if p is not None:
                pts.append(p)
        return pts

    sx_sy = first_pair(observation.get("self_position")) or [0, 0]
    ox_oy = first_pair(observation.get("opponent_position")) or sx_sy
    sx, sy = sx_sy[0], sx_sy[1]
    ox, oy = ox_oy[0], ox_oy[1]

    env = observation.get("environment_name") or observation.get("mode") or "resource_collection"
    role = observation.get("self_role") or observation.get("role") or ""

    gw = observation.get("grid_width") or observation.get("width") or 0
    gh = observation.get("grid_height") or observation.get("height") or 0

    if env == "pursuit_evasion":
        if role == "pursuer":
            return step_toward([sx, sy], [ox, oy])
        corners = [[0, 0], [0, max(0, gh - 1)], [max(0, gw - 1), 0], [max(0, gw - 1), max(0, gh - 1)]]
        best = corners[0]
        best_d = -1
        for c in corners:
            d = manhattan(c, [ox, oy])
            if d > best_d:
                best_d = d
                best = c
        return step_toward([sx, sy], best)

    if env == "territory_control":
        targets = norm_points(observation.get("unclaimed_cells")) or norm_points(observation.get("opponent_territory"))
        if not targets:
            targets = norm_points(observation.get("neutral_cells")) or norm_points(observation.get("frontier")) or []
        if targets:
