            best_score = 10**9
            for t in targets:
                score = manhattan([sx, sy], t)
                if ox != sx or oy != sy:
                    score += 1 if manhattan(t, [ox, oy]) <= manhattan([sx, sy], [ox, oy]) else 0
                if score < best_score:
                    best_score = score
                    best = t
            return step_toward([sx, sy], best)
        return step_toward([sx, sy], [gw // 2 if gw else sx, gh // 2 if gh else sy])

    resources = norm_points(observation.get("resources")) or norm_points(observation.get("resource_positions"))
    if resources:
        best = resources[0]
        best_d = 10**9
        for r in resources:
            d = manhattan([sx, sy], r)
            if d < best_d:
                best_d = d
                best = r
        return step_toward([sx, sy], best)

    if ox != sx or oy != sy:
        return step_toward([sx, sy], [ox, oy])

    return [0, 0]

